export default function TourismGuideTopic() {
  const { slug } = useParams();
  const { language } = useLanguage();
  const [selectedPlace, setSelectedPlace] = useState<Place | null>(null);
  const [selectedCircuit, setSelectedCircuit] = useState<Circuit | null>(null);
  const [activeFilter, setActiveFilter] = useState('all');
  const lang = (['fr', 'ar', 'en', 'it', 'ru'].includes(language) ? language : 'fr') as keyof typeof labels;
  const topic = slug ? topics[slug] : undefined;
  useEffect(() => { setSelectedPlace(null); setSelectedCircuit(null); setActiveFilter('all'); }, [slug]);
  if (!topic) return <Navigate to="/citizens/tourism" replace />;
  const ui = labels[lang];
  const isRTL = lang === 'ar';
  const visiblePlaces = topic.places.filter((place) => slug !== 'nature-randonnees' || matchesLandscape(place, activeFilter));
  const visibleCircuits = circuits.filter((circuit) => slug && circuit.slugs.includes(slug));
  return (
    <div className="min-h-screen bg-gradient-to-b from-white to-gray-50" dir={isRTL ? 'rtl' : 'ltr'}>
      <SEOHead title={`${topic.title} | Dalil Tounes`} description={topic.intro} canonical={`https://dalil-tounes.com/citizens/tourism/guide/${slug}`} currentPath={`/citizens/tourism/guide/${slug}`} />
      <main className="mx-auto max-w-5xl px-4 py-6">
        <Link to="/citizens/tourism" className="inline-flex items-center gap-2 text-sm font-medium text-[#4A1D43] hover:text-[#D4AF37]"><ArrowLeft className={`h-4 w-4 ${isRTL ? 'rotate-180' : ''}`} />{ui.back}</Link>
        <header className="mt-5 border-b border-[#D4AF37]/40 pb-5">
          <h1 className="text-2xl sm:text-3xl font-semibold text-[#4A1D43]" style={{ fontFamily: "'Playfair Display', serif" }}>{topic.title}</h1>
          <p className="mt-2 max-w-3xl text-sm leading-relaxed text-gray-600">{topic.intro}</p>
        </header>
        {visibleCircuits.length > 0 && <section className="mt-5"><div className="mb-3"><div className="flex items-center gap-2"><Route className="h-4 w-4 text-[#D4AF37]" /><h2 className="text-sm font-semibold text-[#4A1D43]">Itinéraires conseillés</h2></div><p className="mt-1 text-[11px] leading-relaxed text-gray-500">Prenez votre temps : parcourez les ruelles, rencontrez les habitants, ressentez l’ambiance et profitez de chaque étape.</p></div><div className="grid gap-2 sm:grid-cols-3">{visibleCircuits.map((circuit) => <button key={circuit.name} type="button" onClick={() => setSelectedCircuit(circuit)} className="group rounded-xl border border-[#D4AF37]/40 bg-white p-3 text-left shadow-sm transition hover:border-[#D4AF37] hover:shadow-md"><div className="flex items-start justify-between gap-2"><span className="text-xs font-semibold text-[#4A1D43]">{circuit.name}</span><span className="shrink-0 rounded-full bg-[#D4AF37]/10 px-2 py-0.5 text-[9px] text-[#4A1D43]">{circuit.duration}</span></div><p className="mt-1 text-[10px] leading-relaxed text-gray-500">{circuit.subtitle}</p><p className="mt-2 text-[10px] font-medium text-[#8A6A12]">{circuit.stages.join(' → ')}</p></button>)}</div></section>}
        {slug === 'marches-gastronomie' && <section className="mt-5 rounded-xl border border-[#D4AF37]/35 bg-[#FFFDF8] p-4"><div className="flex items-center gap-2"><CalendarDays className="h-4 w-4 text-[#D4AF37]" /><h2 className="text-sm font-semibold text-[#4A1D43]">Le calendrier des saveurs</h2></div><p className="mt-1 text-[11px] leading-relaxed text-gray-500">Des repères simples pour découvrir les produits lorsqu’ils sont au cœur de la vie locale.</p><div className="mt-3 grid gap-2 sm:grid-cols-2">{foodSeasons.map((season) => <div key={season.period} className="rounded-lg border border-[#D4AF37]/25 bg-white px-3 py-2.5"><p className="text-[10px] font-semibold uppercase tracking-wide text-[#9A7517]">{season.period}</p><p className="mt-0.5 text-xs font-semibold text-[#4A1D43]">{season.label}</p><p className="mt-0.5 text-[10px] text-gray-500">{season.region}</p></div>)}</div><p className="mt-2 text-[10px] leading-relaxed text-gray-400">Les périodes peuvent varier selon la région, la météo et la récolte.</p></section>}
        {slug === 'nature-randonnees' && <div className="mt-4 flex gap-2 overflow-x-auto pb-1" aria-label="Filtrer par paysage">{landscapeFilters.map((filter) => <button key={filter.id} type="button" onClick={() => setActiveFilter(filter.id)} aria-pressed={activeFilter === filter.id} className={`shrink-0 rounded-full border px-3 py-1.5 text-xs font-medium transition ${activeFilter === filter.id ? 'border-[#4A1D43] bg-[#4A1D43] text-white' : 'border-[#D4AF37]/50 bg-white text-[#4A1D43] hover:border-[#D4AF37]'}`}>{filter.label}</button>)}</div>}
        <section className="mt-5 grid gap-3 sm:grid-cols-2">
          {visiblePlaces.map((place) => (
            <article key={place.name} className="overflow-hidden rounded-xl border border-[#D4AF37]/45 bg-white shadow-sm transition hover:-translate-y-0.5 hover:shadow-md">
              {place.image && <div className="relative"><img src={place.image} alt={place.name} loading="lazy" className="h-36 w-full object-cover" onError={(event) => { event.currentTarget.src = '/images/drapeau-tunisie.webp'; event.currentTarget.className = 'h-36 w-full bg-gray-50 object-contain p-6'; }} />{unescoStatus(place) && <span className={`absolute right-2 top-2 rounded-full border px-2 py-1 text-[9px] font-semibold shadow-sm backdrop-blur-sm ${unescoStatus(place) === 'world' || unescoStatus(place) === 'intangible' ? 'border-[#D4AF37] bg-[#4A1D43]/95 text-[#F8E7A1]' : 'border-white/80 bg-white/95 text-[#4A1D43]'}`}>{unescoStatus(place) === 'world' ? 'UNESCO · Patrimoine mondial' : unescoStatus(place) === 'intangible' ? 'UNESCO · Patrimoine immatériel' : 'UNESCO · Liste indicative'}</span>}</div>}
              <div className="p-4">
                <div className="flex items-start justify-between gap-3"><h2 className="text-base font-semibold text-[#4A1D43]">{place.name}</h2><span className="inline-flex shrink-0 items-center gap-1 text-[11px] text-gray-500"><MapPin className="h-3.5 w-3.5 text-[#D4AF37]" />{place.region}</span></div>
                <p className="mt-2 text-xs leading-relaxed text-gray-600">{place.text}</p>
                <div className="mt-3 flex flex-wrap gap-1.5">{place.tags.map((tag) => <span key={tag} className="rounded-full bg-[#D4AF37]/10 px-2 py-1 text-[10px] text-[#4A1D43]">{tag}</span>)}</div>
                {(place.mapQuery || place.practical) && <button type="button" onClick={() => setSelectedPlace(place)} className="mt-3 inline-flex items-center gap-1.5 text-xs font-semibold text-[#4A1D43] hover:text-[#D4AF37]"><Info className="h-3.5 w-3.5" />{ui.discover}</button>}
              </div>
            </article>
          ))}
        </section>
        <aside className="mt-5 rounded-xl border border-[#D4AF37] bg-[#FFFDF8] p-4"><h2 className="text-sm font-semibold text-[#4A1D43]">{ui.useful}</h2><p className="mt-1 text-xs leading-relaxed text-gray-600">{slug && topicNotes[slug] ? topicNotes[slug] : ui.note}</p></aside>
        <div className="mt-5 flex flex-col gap-2 sm:flex-row">
          <Link to={`/recherche?q=${encodeURIComponent(topic.query)}`} className="inline-flex items-center justify-center gap-2 rounded-lg border border-[#D4AF37] bg-[#4A1D43] px-4 py-2.5 text-sm font-semibold text-[#D4AF37]"><Search className="h-4 w-4" />{ui.pros}</Link>
          {topic.source && <a href={topic.source} target="_blank" rel="noopener noreferrer" className="inline-flex items-center justify-center gap-2 rounded-lg border border-[#D4AF37]/60 bg-white px-4 py-2.5 text-sm font-semibold text-[#4A1D43]"><ExternalLink className="h-4 w-4" />{ui.source}</a>}
        </div>
      </main>
      {selectedCircuit && (
        <div className="fixed inset-0 z-[100] flex items-end justify-center bg-black/55 p-0 sm:items-center sm:p-4" role="dialog" aria-modal="true" aria-label={selectedCircuit.name} onMouseDown={(event) => { if (event.target === event.currentTarget) setSelectedCircuit(null); }}>
          <div className="max-h-[92vh] w-full max-w-lg overflow-y-auto rounded-t-2xl bg-white p-5 shadow-2xl sm:rounded-2xl">
            <div className="flex items-start justify-between gap-4"><div><p className="text-[10px] font-semibold uppercase tracking-wider text-[#B38A16]">Itinéraire conseillé</p><h2 className="mt-1 text-xl font-semibold text-[#4A1D43]">{selectedCircuit.name}</h2><p className="mt-1 text-xs text-gray-500">{selectedCircuit.subtitle}</p></div><button type="button" onClick={() => setSelectedCircuit(null)} aria-label={ui.close} className="rounded-full bg-gray-50 p-2 text-[#4A1D43]"><X className="h-4 w-4" /></button></div>
            <div className="mt-5 flex items-center overflow-x-auto pb-1">{selectedCircuit.stages.map((stage, index) => <div key={stage} className="flex shrink-0 items-center"><span className="rounded-full border border-[#D4AF37] bg-[#FFFDF8] px-3 py-1.5 text-xs font-semibold text-[#4A1D43]">{stage}</span>{index < selectedCircuit.stages.length - 1 && <span className="mx-2 text-[#D4AF37]">→</span>}</div>)}</div>
            <div className="mt-4 grid grid-cols-2 gap-2"><div className="rounded-lg bg-[#FFF9E9] p-3"><p className="text-[10px] font-semibold text-[#4A1D43]">Durée conseillée</p><p className="mt-1 text-xs text-gray-600">{selectedCircuit.duration}</p></div><div className="rounded-lg bg-[#FFF9E9] p-3"><p className="text-[10px] font-semibold text-[#4A1D43]">Distance indicative</p><p className="mt-1 text-xs text-gray-600">{selectedCircuit.distance}</p></div><div className="col-span-2 rounded-lg bg-gray-50 p-3"><p className="text-[10px] font-semibold text-[#4A1D43]">Meilleure période</p><p className="mt-1 text-xs text-gray-600">{selectedCircuit.bestTime}</p></div></div>
            <div className="mt-3 flex gap-3 rounded-lg border-l-2 border-[#D4AF37] bg-[#FFFDF8] p-3"><Info className="mt-0.5 h-4 w-4 shrink-0 text-[#4A1D43]" /><p className="text-xs leading-relaxed text-gray-600">{selectedCircuit.advice}</p></div>
            <p className="mt-3 text-[10px] leading-relaxed text-gray-400">Les distances sont indicatives et peuvent varier selon le point de départ, la route choisie et les accès ouverts.</p>
            <div className="mt-4 flex flex-col gap-2 sm:flex-row"><a href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(selectedCircuit.mapQuery)}`} target="_blank" rel="noopener noreferrer" className="inline-flex flex-1 items-center justify-center gap-2 rounded-lg bg-[#4A1D43] px-4 py-2.5 text-sm font-semibold text-[#D4AF37]"><Navigation className="h-4 w-4" />Voir le parcours</a><Link to={`/recherche?q=${encodeURIComponent(`guide excursion ${selectedCircuit.stages.join(' ')}`)}`} className="inline-flex flex-1 items-center justify-center gap-2 rounded-lg border border-[#D4AF37] px-4 py-2.5 text-center text-xs font-semibold text-[#4A1D43]"><Search className="h-4 w-4" />Guides et services</Link></div>
          </div>
        </div>
      )}
      {selectedPlace && (
        <div className="fixed inset-0 z-[100] flex items-end justify-center bg-black/55 p-0 sm:items-center sm:p-4" role="dialog" aria-modal="true" aria-label={selectedPlace.name} onMouseDown={(event) => { if (event.target === event.currentTarget) setSelectedPlace(null); }}>
          <div className="max-h-[92vh] w-full max-w-lg overflow-y-auto rounded-t-2xl bg-white shadow-2xl sm:rounded-2xl">
            <div className="relative">
              {selectedPlace.image && <img src={selectedPlace.image} alt={selectedPlace.name} className="h-48 w-full object-cover sm:h-56" onError={(event) => { event.currentTarget.src = '/images/drapeau-tunisie.webp'; event.currentTarget.className = 'h-48 w-full bg-gray-50 object-contain p-8 sm:h-56'; }} />}
              <button type="button" onClick={() => setSelectedPlace(null)} aria-label={ui.close} className="absolute right-3 top-3 rounded-full bg-white/95 p-2 text-[#4A1D43] shadow"><X className="h-4 w-4" /></button>
            </div>
            <div className="p-5">
              <div className="flex items-start justify-between gap-3"><h2 className="text-xl font-semibold text-[#4A1D43]">{selectedPlace.name}</h2><span className="inline-flex shrink-0 items-center gap-1 text-xs text-gray-500"><MapPin className="h-3.5 w-3.5 text-[#D4AF37]" />{selectedPlace.region}</span></div>
              <p className="mt-2 text-sm leading-relaxed text-gray-600">{selectedPlace.text}</p>
              {selectedPlace.history && <div className="mt-4 rounded-lg border-l-2 border-[#D4AF37] bg-[#FFFDF8] p-3"><p className="text-xs font-semibold text-[#4A1D43]">{ui.history}</p><p className="mt-1 text-xs leading-relaxed text-gray-600">{selectedPlace.history}</p></div>}
              <div className="mt-4"><p className="text-xs font-semibold text-[#4A1D43]">Préparer la visite</p><div className="mt-2 grid grid-cols-2 gap-2 text-[11px]"><div className="rounded-lg bg-gray-50 p-2.5"><p className="font-semibold text-[#4A1D43]">Durée conseillée</p><p className="mt-0.5 text-gray-600">{getVisitInfo(selectedPlace, slug).duration}</p></div><div className="rounded-lg bg-gray-50 p-2.5"><p className="font-semibold text-[#4A1D43]">Niveau</p><p className="mt-0.5 text-gray-600">{getVisitInfo(selectedPlace, slug).level}</p></div><div className="rounded-lg bg-gray-50 p-2.5"><p className="font-semibold text-[#4A1D43]">Accès en voiture</p><p className="mt-0.5 text-gray-600">{getVisitInfo(selectedPlace, slug).car}</p></div><div className="rounded-lg bg-gray-50 p-2.5"><p className="font-semibold text-[#4A1D43]">Avec des enfants</p><p className="mt-0.5 text-gray-600">{getVisitInfo(selectedPlace, slug).family}</p></div><div className="col-span-2 rounded-lg bg-[#FFF9E9] p-2.5"><p className="font-semibold text-[#4A1D43]">Accompagnement</p><p className="mt-0.5 text-gray-600">{getVisitInfo(selectedPlace, slug).guide}</p></div></div><p className="mt-2 text-[9px] leading-relaxed text-gray-400">Informations indicatives : vérifiez toujours la météo, l’ouverture, l’état des accès et les conditions locales avant le départ.</p></div>
              {selectedPlace.bestTime && <div className="mt-4 flex gap-3 rounded-lg bg-[#FFF9E9] p-3"><CalendarDays className="mt-0.5 h-4 w-4 shrink-0 text-[#B38A16]" /><div><p className="text-xs font-semibold text-[#4A1D43]">{ui.period}</p><p className="mt-0.5 text-xs leading-relaxed text-gray-600">{selectedPlace.bestTime}</p></div></div>}
              {selectedPlace.practical && <div className="mt-2 flex gap-3 rounded-lg bg-gray-50 p-3"><Info className="mt-0.5 h-4 w-4 shrink-0 text-[#4A1D43]" /><div><p className="text-xs font-semibold text-[#4A1D43]">{ui.practical}</p><p className="mt-0.5 text-xs leading-relaxed text-gray-600">{selectedPlace.practical}</p></div></div>}
              <div className="mt-4 flex flex-col gap-2 sm:flex-row">
                {selectedPlace.mapQuery && <a href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(selectedPlace.mapQuery)}`} target="_blank" rel="noopener noreferrer" className="inline-flex flex-1 items-center justify-center gap-2 rounded-lg bg-[#4A1D43] px-4 py-2.5 text-sm font-semibold text-[#D4AF37]"><Navigation className="h-4 w-4" />{ui.route}</a>}
                <Link to={`/recherche?q=${encodeURIComponent(`${topic.query} ${selectedPlace.region}`)}`} className="inline-flex flex-1 items-center justify-center gap-2 rounded-lg border border-[#D4AF37] px-4 py-2.5 text-center text-xs font-semibold text-[#4A1D43]"><Search className="h-4 w-4" />{ui.pros}</Link>
              </div>
              {selectedPlace.officialUrl && <a href={selectedPlace.officialUrl} target="_blank" rel="noopener noreferrer" className="mt-2 inline-flex w-full items-center justify-center gap-2 rounded-lg border border-[#4A1D43]/30 bg-[#FFFDF8] px-4 py-2.5 text-xs font-semibold text-[#4A1D43] hover:border-[#D4AF37]"><ExternalLink className="h-4 w-4" />{ui.eventSite}</a>}
              {selectedPlace.photoSource && <a href={selectedPlace.photoSource} target="_blank" rel="noopener noreferrer" className="mt-3 inline-flex items-center gap-1 text-[10px] text-gray-400 hover:text-[#4A1D43]"><ExternalLink className="h-3 w-3" />{ui.photo}</a>}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
